var ROMAN_VALS=[[1000,'M'],[900,'CM'],[500,'D'],[400,'CD'],[100,'C'],[90,'XC'],[50,'L'],[40,'XL'],[10,'X'],[9,'IX'],[5,'V'],[4,'IV'],[1,'I']];
function toRoman(num){
  num=Math.floor(Number(num));
  if(!isFinite(num)||num<1||num>3999) throw new Error('范围限定 1–3999');
  var out='';
  for(var i=0;i<ROMAN_VALS.length;i++){
    while(num>=ROMAN_VALS[i][0]){ out+=ROMAN_VALS[i][1]; num-=ROMAN_VALS[i][0]; }
  }
  return out;
}
var ROMAN_MAP={I:1,V:5,X:10,L:50,C:100,D:500,M:1000};
function fromRoman(str){
  str=String(str).toUpperCase().replace(/\s+/g,'');
  if(!/^[IVXLCDM]+$/.test(str)) throw new Error('仅含合法罗马字符 I V X L C D M');
  var total=0;
  for(var i=0;i<str.length;i++){
    var cur=ROMAN_MAP[str[i]], nxt=ROMAN_MAP[str[i+1]]||0;
    total += (nxt>cur) ? -cur : cur;
  }
  return total;
}
function normalizeRoman(s){ return toRoman(fromRoman(s)); }
function isCanonical(s){ return toRoman(fromRoman(s))===String(s).toUpperCase().replace(/\s+/g,''); }
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { toRoman:toRoman, fromRoman:fromRoman, normalizeRoman:normalizeRoman, isCanonical:isCanonical };
}
if (typeof window !== 'undefined') {
  window.RomanForgePure = { toRoman:toRoman, fromRoman:fromRoman, normalizeRoman:normalizeRoman, isCanonical:isCanonical };
